// Code generated by scripts/split-effects (#5906, ADR 0225). DO NOT EDIT.

package effectstest

// The flat view of the effects tree, for the tests that scan its sources.
//
// Before the split (#5906) every card, every core file and every test sat in
// one directory, and a lint test read its own directory: filepath.Glob("*.go"),
// os.ReadDir("."), os.ReadFile(name), parser.ParseFile(fset, name, nil, 0). The
// split moved those tests two levels down and the cards into shards, so
// scripts/split-effects rewrote those calls to the Flat* functions below. They
// behave like the os, filepath and parser calls they replace, except that a
// bare file name (no directory) is looked up in the whole tree as if it were
// still one directory: the core, every card shard and every test package
// (effectstest and the generated main_test.go files are left out). A path with
// a directory is passed through unchanged.
//
// The source a Flat function returns is the file with the qualifier of every
// effects-tree package removed (effects.Register(effects.Spec{...}) reads as
// Register(Spec{...})), so a scan written against the one-package source keeps
// matching. Line numbers are unchanged; columns move.

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/fs"
	"os"
	"path/filepath"
	"runtime"
	"sort"
	"strconv"
	"strings"
	"sync"
)

const effectsImport = "github.com/krakenhavoc/cmd_and_ctrl/server/internal/cards/effects"

var (
	flatOnce  sync.Once
	flatIndex map[string]string // base name → path
	flatNames []string
	flatErr   error
)

// EffectsDir is the directory of package effects (the core).
func EffectsDir() string {
	_, file, _, ok := runtime.Caller(0)
	if !ok {
		panic("effectstest: no caller information")
	}
	return filepath.Dir(filepath.Dir(file))
}

func flatLoad() {
	root := EffectsDir()
	flatIndex = map[string]string{}
	add := func(dir string, onlyTests bool) {
		es, err := os.ReadDir(dir)
		if err != nil {
			flatErr = err
			return
		}
		for _, e := range es {
			n := e.Name()
			if e.IsDir() || !strings.HasSuffix(n, ".go") {
				continue
			}
			if onlyTests && (!strings.HasSuffix(n, "_test.go") || n == "main_test.go") {
				continue
			}
			if prev, dup := flatIndex[n]; dup {
				flatErr = fmt.Errorf("effectstest: %s and %s share a file name; the flat view needs unique names", prev, filepath.Join(dir, n))
				return
			}
			flatIndex[n] = filepath.Join(dir, n)
		}
	}
	add(root, false)
	for _, sub := range []string{"cards", "tests"} {
		es, _ := os.ReadDir(filepath.Join(root, sub))
		for _, e := range es {
			if e.IsDir() {
				add(filepath.Join(root, sub, e.Name()), sub == "tests")
			}
		}
	}
	for n := range flatIndex {
		flatNames = append(flatNames, n)
	}
	sort.Strings(flatNames)
}

// flatPath resolves a bare name in the flat view; ok is false for anything
// else, which the caller passes through to the real file system.
func flatPath(name string) (string, bool) {
	name = strings.TrimPrefix(name, "./")
	if strings.ContainsRune(name, '/') || strings.ContainsRune(name, filepath.Separator) {
		return "", false
	}
	flatOnce.Do(flatLoad)
	p, ok := flatIndex[name]
	return p, ok
}

// FlatSource is a file of the tree with the effects-tree qualifiers removed.
func FlatSource(path string) ([]byte, error) {
	src, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, path, src, parser.ImportsOnly)
	if err != nil {
		return src, nil
	}
	quals := map[string]bool{}
	for _, im := range f.Imports {
		p, _ := strconv.Unquote(im.Path.Value)
		if p != effectsImport && !strings.HasPrefix(p, effectsImport+"/") {
			continue
		}
		name := p[strings.LastIndex(p, "/")+1:]
		if im.Name != nil {
			name = im.Name.Name
		}
		if name != "_" && name != "." {
			quals[name] = true
		}
	}
	if len(quals) == 0 {
		return src, nil
	}
	f, err = parser.ParseFile(fset, path, src, parser.SkipObjectResolution)
	if err != nil {
		return src, nil
	}
	tf := fset.File(f.Pos())
	var cut []int // start offsets of "qual." to delete
	ast.Inspect(f, func(n ast.Node) bool {
		se, ok := n.(*ast.SelectorExpr)
		if !ok {
			return true
		}
		if x, ok := se.X.(*ast.Ident); ok && quals[x.Name] {
			cut = append(cut, tf.Offset(x.Pos()), len(x.Name)+1)
		}
		return true
	})
	var out bytes.Buffer
	pos := 0
	for i := 0; i < len(cut); i += 2 {
		out.Write(src[pos:cut[i]])
		pos = cut[i] + cut[i+1]
	}
	out.Write(src[pos:])
	return out.Bytes(), nil
}

// FlatGlob is filepath.Glob over the flat view for a pattern with no
// directory; it returns base names, as Glob("*.go") did in the old package.
func FlatGlob(pattern string) ([]string, error) {
	if strings.ContainsRune(pattern, '/') {
		return filepath.Glob(pattern)
	}
	flatOnce.Do(flatLoad)
	if flatErr != nil {
		return nil, flatErr
	}
	var out []string
	for _, n := range flatNames {
		ok, err := filepath.Match(pattern, n)
		if err != nil {
			return nil, err
		}
		if ok {
			out = append(out, n)
		}
	}
	return out, nil
}

type flatEntry struct {
	name, path string
}

func (e flatEntry) Name() string               { return e.name }
func (e flatEntry) IsDir() bool                { return false }
func (e flatEntry) Type() fs.FileMode          { return 0 }
func (e flatEntry) Info() (fs.FileInfo, error) { return os.Stat(e.path) }

// FlatReadDir is os.ReadDir, with "." (or "") listing the flat view.
func FlatReadDir(name string) ([]os.DirEntry, error) {
	if name != "." && name != "" && name != "./" {
		return os.ReadDir(name)
	}
	flatOnce.Do(flatLoad)
	if flatErr != nil {
		return nil, flatErr
	}
	out := make([]os.DirEntry, 0, len(flatNames))
	for _, n := range flatNames {
		out = append(out, flatEntry{n, flatIndex[n]})
	}
	return out, nil
}

// FlatReadFile is os.ReadFile; a bare name reads the flat source.
func FlatReadFile(name string) ([]byte, error) {
	if p, ok := flatPath(name); ok {
		return FlatSource(p)
	}
	return os.ReadFile(name)
}

// FlatOpen is os.Open; a bare name opens the file wherever it now lives.
func FlatOpen(name string) (*os.File, error) {
	if p, ok := flatPath(name); ok {
		return os.Open(p)
	}
	return os.Open(name)
}

// FlatStat is os.Stat; a bare name stats the file wherever it now lives.
func FlatStat(name string) (os.FileInfo, error) {
	if p, ok := flatPath(name); ok {
		return os.Stat(p)
	}
	return os.Stat(name)
}

// FlatParseFile is parser.ParseFile; with no src, a bare name parses the
// flat source (and keeps the bare name as the file name in fset).
func FlatParseFile(fset *token.FileSet, filename string, src any, mode parser.Mode) (*ast.File, error) {
	if src == nil {
		if p, ok := flatPath(filename); ok {
			b, err := FlatSource(p)
			if err != nil {
				return nil, err
			}
			src = b
		}
	}
	return parser.ParseFile(fset, filename, src, mode)
}
